"""Build self-contained exact-loader worker-policy probe from fitted model."""
import base64,gzip,json,argparse
parser=argparse.ArgumentParser(); parser.add_argument('--model',default='worker_model.txt'); parser.add_argument('--out',default='student_model.py'); args=parser.parse_args()
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
model=(ROOT/'experiments/v59_state_teacher'/args.model).read_bytes()
report=json.loads((ROOT/'experiments/v59_state_teacher'/args.model.replace('.txt','.metrics.json')).read_text())
classes=report['classes']; keys=report['feature_names']
encoded=base64.b85encode(gzip.compress(model,compresslevel=9)).decode()
source=(ROOT/'experiments/v57_broad/v57_reset_candidate.py').read_text()
source+='''\n# v59 learned worker-action controller; farmer and market retain frozen reset-v57 scaffold.\nimport base64 as _v59_b64, gzip as _v59_gzip, json as _v59_json\n_V59_MODEL_B85 = r"'''+encoded+'''"\n_V59_CLASSES = '''+repr(classes)+'''\n_V59_KEYS = '''+repr(keys)+'''\n_V59_RUNTIME = {}\ndef _v59_features(obs, seat, actor):\n    farm=obs["farms"][seat]; coords=[farm.get("farmer",[0,0]),*farm.get("hands",[])]\n    pos=coords[actor] if actor<len(coords) else [0,0]\n    x,y=int(pos[0]),int(pos[1]); tiles=farm.get("tiles",[])\n    tile=tiles[y][x] if y<len(tiles) and x<len(tiles[y]) and isinstance(tiles[y][x],dict) else {}\n    inventories=obs.get("private",{}).get("inventories",[]); inv=inventories[actor] if actor<len(inventories) else {}\n    targets={"yield":[],"crop":[],"animal":[],"unfed":[],"fertilizer":[]}\n    for yy,row in enumerate(tiles):\n        for xx,t in enumerate(row):\n            if not isinstance(t,dict): continue\n            if t.get("yield_units",0)>0: targets["yield"].append((xx,yy))\n            if t.get("crop"): targets["crop"].append((xx,yy))\n            if t.get("animal"): targets["animal"].append((xx,yy))\n            if t.get("animal") and not t.get("fed_today"): targets["unfed"].append((xx,yy))\n            if t.get("fertilizer_available"): targets["fertilizer"].append((xx,yy))\n    f={"actor":actor,"x":x,"y":y,"tile_kind":tile.get("kind","EMPTY"),"crop":tile.get("crop","none"),\n       "yield_here":int(tile.get("yield_units",0) or 0),"watered":int(bool(tile.get("watered"))),\n       "animal_here":tile.get("animal","none"),"fed_today":int(bool(tile.get("fed_today"))),\n       "carry":tuple(sorted((k,int(v)) for k,v in inv.items() if isinstance(v,(int,float)) and v)),\n       "day":int(obs.get("day",0) or 0),"hour":int(obs.get("hour",0) or 0),\n       "cash_bin":int(float(farm.get("money",0) or 0)//5000),\n       "shops":len(obs.get("town",{}).get("unlocked_shops",[]))}\n    for n,pts in targets.items(): f["near_"+n]=min((abs(x-a)+abs(y-b) for a,b in pts),default=99)\n    return f\ndef _v59_predict(obs, seat, teacher_action):\n    if not _V59_RUNTIME:\n        import lightgbm as _v59_lgb, pandas as _v59_pd\n        _V59_RUNTIME["model"]=_v59_lgb.Booster(model_str=_v59_gzip.decompress(_v59_b64.b85decode(_V59_MODEL_B85)).decode())\n        _V59_RUNTIME["pd"]=_v59_pd\n        _V59_RUNTIME["categories"]=_V59_RUNTIME["model"].pandas_categorical\n    model=_V59_RUNTIME["model"]; pd=_V59_RUNTIME["pd"]; categories=_V59_RUNTIME["categories"]\n    farm=obs["farms"][seat]; count=len(farm.get("hands",[])); feats=[_v59_features(obs,seat,i+1) for i in range(count)]\n    if not feats: return []\n    frame=pd.DataFrame([{k:str(f.get(k,"")) for k in _V59_KEYS} for f in feats])\n    for i,k in enumerate(_V59_KEYS): frame[k]=pd.Categorical(frame[k],categories=categories[i])\n    preds=model.predict(frame).argmax(axis=1)\n    labels=[_V59_CLASSES[int(i)] for i in preds]\n    templates={}\n    for cmd in [teacher_action.get("farmer",["PASS"]),*teacher_action.get("hands",[])]:\n        if isinstance(cmd,list): templates["|".join(map(str,cmd[:2]))]=cmd\n    out=[]\n    for i,lab in enumerate(labels):\n        prior=teacher_action.get("hands",[])[i] if i<len(teacher_action.get("hands",[])) else ["PASS"]\n        out.append(list(templates.get(lab,prior)))\n    return out\n_v59_teacher_agent=agent\ndef agent(obs,configuration=None):\n    action=_v59_teacher_agent(obs,configuration)\n    try:\n        seat=int(obs.get("player",0)); action["hands"]=_v59_predict(obs,seat,action)\n    except Exception:\n        pass\n    return action\n\ndef _kaggle_submission_entrypoint(obs,configuration=None): return agent(obs,configuration)\n'''
out=ROOT/'experiments/v59_state_teacher'/args.out; out.write_text(source)
print(json.dumps({'bytes':out.stat().st_size,'sha256':__import__('hashlib').sha256(out.read_bytes()).hexdigest(),'model_bytes':len(model),'compressed':len(encoded)}))
